  this.mainTrack=track('main.traveler',DECK.cockpitHalfWidth*2,true,0,DECK.mainTrackY,DECK.mainTrackZ);this.mainCar=carriage('main.traveler');this.mainCarSheave=this.registerControl(this.mesh(new THREE.TorusGeometry(.044,.012,6,20),black.clone()),'main.traveler');
